(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["id"] = {"ui":{"skip":"Langsung ke isi","back":"← Kembali ke AI-gile","lang.button":"Bahasa: {name}","lang.dialog":"Pilih bahasa","lang.search":"Cari bahasa","lang.none":"Tidak ada bahasa yang cocok","lang.notYet":"{name} belum diterjemahkan","theme.aria":"Ganti tema: terang, gelap, atau hitam","theme.toLight":"Ganti ke tema terang","theme.toDark":"Ganti ke tema gelap","theme.toBlack":"Ganti ke tema hitam (hitam pekat, nyaman untuk layar OLED)","words.underline":"Garis bawahi kata-kata ini di halaman","words.underlineHelp":"Arahkan kursor atau ketuk kata bergaris titik-titik untuk melihat artinya.","index.title":"AI-gile: tim dev AI-mu, dalam satu papan","index.description":"AI-gile adalah papan kanban untuk tim pemrograman AI. Mereka bekerja saat kamu tidur; kamu cukup mengurus satu tumpukan pendek: hal yang perlu diputuskan, dites, dan disetujui.","hero.logoAlt":"Ikon papan AI-gile","hero.h1.html":"Tim dev AI-mu, dalam satu&nbsp;papan.","hero.alpha":"🐣 Pra-alfa tertutup","hero.alphaTitle":"Masih awal dan belum selesai: terima kasih sudah mau mencoba!","hero.lede":"Mereka membangun selagi kamu tidur. Kamu bangun dan menemukan satu tumpukan pendek: beberapa pertanyaan, beberapa hal untuk dites, satu atau dua berlian ungu. Klik, setujui, lanjut ngopi.","dl.windows":"Aplikasi Windows","dl.browser":"Jalankan di browser","dl.messenger":"📱 Messenger untuk ponselmu","dl.soon":"Segera hadir","dl.notify":"🔔 Kabari aku saat dibuka","dl.notifySmall":"Alfa atau beta","hero.secondary":"Agile, tapi timnya tidak butuh kopi stand-up. (Stand-up tetap jalan, sih.)","pitch.h2":"AI-gile dalam sebanyak kata yang kamu mau","pitch.lede":"Pilih panjangnya, dari satu kata sampai 144. Setiap panjang punya deskripsinya sendiri, ditulis khusus untuk ukuran itu. Geser slider atau pakai tombol panah.","pitch.rangeLabel":"Panjang dalam kata","pitch.dice":"🎲 versi lain","pitch.words.one":"{n} kata","pitch.words.other":"{n} kata","pitch.letters.one":"{n} huruf","pitch.letters.other":"{n} huruf","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karakter","count.line.html.one":"{n} kartu di papan sekarang","count.line.html.other":"{n} kartu di papan sekarang","people.humans.html.one":"👥 {n} manusia","people.humans.html.other":"👥 {n} manusia","people.agents.html.one":"🤖 {n} agen","people.agents.html.other":"🤖 {n} agen","people.working.html.one":"⚡ {n} sedang bekerja sekarang","people.working.html.other":"⚡ {n} sedang bekerja sekarang","pre.title":"AI-gile: ada yang sedang dibangun","pre.description":"Ada sesuatu yang sedang dibangun di sini. Papan tempat tim AI membangun apa yang kamu minta, sambil mengajarimu di sepanjang jalan. Untuk sekarang, pra-alfa tertutup bersama teman-teman.","pre.h1":"Ada sesuatu yang sedang dibangun di sini. 🤫","pre.line":"Papan tempat tim AI membangun apa yang kamu minta, sambil mengajarimu di sepanjang jalan. Untuk sekarang, pra-alfa tertutup bersama teman-teman.","pre.btn":"🔔 Kabari aku saat dibuka","pre.peek":"Di balik kaca: papan yang asli, langsung. Setiap kartu adalah batang berwarna.","pre.peekFake":"Di balik kaca: seperti inilah papan yang sedang bekerja.","features.aria":"Apa yang dilakukannya","f.pile.h":"Satu tumpukan untukmu","f.pile.html":"<b>Untukmu</b> berisi semua yang menunggumu, dari semua proyek: pertanyaan, hal untuk dites, tugas yang hanya bisa dikerjakan manusia. Antreanmu memberi tahu apa yang berikutnya dan berapa lama.","f.sleep.h":"Tim yang bekerja saat kamu tidur","f.sleep.p":"Setiap proyek punya lead dan tim agen AI. Beri komentar di sebuah kartu, tim pun bangun, mengerjakannya, lalu mengembalikannya dengan langkah-langkah yang bisa diikuti manusia yang sedang capek.","f.tester.h":"Penguji AI memeriksa lebih dulu","f.tester.p":"Sebelum sampai ke kamu, penguji mengikuti langkah-langkahnya di salinan aplikasi dan menunjukkan apa yang dilihatnya, lengkap dengan tangkapan layar. Telusuri yang lolos dan setujui dengan satu klik.","f.proof.h":"Bukti, bukan janji","f.proof.p":"Setiap serah terima menunjukkan apa yang berubah: berkas, diff, tangkapan layar. Tidak perlu membuka satu per satu aplikasi untuk tahu sudah selesai atau belum.","f.chat.h":"Ngobrol dengan lead-mu","f.chat.p":"Bilah ala Discord: satu ikon per proyek, berlian ungu untuk yang butuh kamu. Kirim ide ke lead; ia mengubahnya jadi kartu dan rencana, dengan tombol ✅ Go.","f.tidy.h":"Rapi dengan sendirinya","f.tidy.p":"Kartu yang berkaitan digabung jadi satu, judul yang berantakan dibereskan, dan pemeriksaan token menjaga kode tetap ramping. Lebih sedikit yang harus dipindah-pindah, lebih sedikit yang harus dipikirkan.","f.private.h":"Milikmu, di komputermu","f.private.li1":"Papan berjalan di mesinmu sendiri dan hanya menjawab kamu.","f.private.li2":"Pesan pribadi antarmanusia dienkripsi ujung ke ujung.","f.private.li3":"Tanpa akun, tanpa pelacak, tanpa cookie.","f.lang.h":"Dalam bahasamu","f.lang.p":"Lebih dari 120 bahasa, dari Belanda, Wales, dan Jepang sampai bajak laut, Yoda, dan Klingon, dengan tombol cepat kembali ke bahasa Inggris untuk istilah industri.","f.service.h":"Dari ide menjadi layanan sungguhan","f.service.p":"Sudah membangun sesuatu dengan AI yang kini dipakai orang? Tandai sebagai layanan dan papan membantumu menjalankannya dengan baik: cek uptime, halaman status publik, insiden dengan laporan tertulis, perubahan yang perlu Go, cadangan yang dicek setiap hari. Bantuan mengajarkan setiap langkah sambil jalan.","msgr.h2":"AI-gile Messenger: timmu di dalam saku","msgr.p1":"Ngobrol dengan tim AI-mu tanpa membuka board. Chat dengan lead proyekmu dan teman-temanmu, lihat langkah tes sebuah kartu lalu jawab, semuanya dari ponselmu.","msgr.p2":"Untuk menyambungkannya, pindai kode QR di board-mu. Baru pertama kali? Chat demo yang ramah akan mengajakmu berkeliling.","msgr.when":"Android dulu, lalu versi web untuk ponsel dan iPhone.","msgr.who":"Lead proyekmu","msgr.b1":"Perbaikan mode gelap sudah siap. Mau langkah tesnya?","msgr.b2":"Mau dong!","msgr.b3":"1. Buka Pengaturan. 2. Pilih Gelap. Sudah kelihatan benar?","tl.aria":"Lini masa dari percakapan pertama sampai peta jalan","tl.h2":"Dari obrolan pertama sampai yang berikutnya","tl.lede":"Tanggal dan jam sungguhan, dalam zona waktumu sendiri. Setelah hari ini, itu baru rencana, tanpa janji tanggal.","tl.today":"Hari ini","tl.planned":"direncanakan","tl.doing":"dikerjakan","tl.cards.one":"{n} kartu","tl.cards.other":"{n} kartu","join.h2":"Ikut serta","join.lede":"AI-gile dibuat oleh seorang nyentrik berjenggot yang punya AuDHD dan beberapa pergulatan dengan kesehatan mental, serta banyak agen yang sabar. Untuk sekarang masih privat, alfa tertutup bersama teman-teman. Mau ikut coba saat dibuka?","join.btn":"Daftarkan minat","join.small":"Kami kirim email, tidak lebih","footer.tag":"AI-gile. Tanpa pelacak, tanpa cookie, tanpa kopi stand-up.","footer.licence":"Lisensi bisnis","footer.status":"Status","footer.privacy":"Apa yang kami simpan","footer.thanks":"Panggilan berkat ChilledChat","form.sending":"Mengirim…","form.failed":"Belum berhasil: coba lagi nanti.","form.offline":"AI-gile tidak terjangkau: coba lagi nanti.","form.keep":"Kami hanya memakai ini untuk membalasmu, lalu menghapusnya. Tanpa pelacak, tanpa cookie.","form.keepLink":"Apa yang kami simpan","interest.title":"AI-gile: kabari aku saat alfa dibuka","interest.description":"Tinggalkan emailmu untuk tahu kapan alfa atau beta tertutup AI-gile dibuka.","interest.h1":"🔔 Kabari aku saat dibuka","interest.lede":"AI-gile masih dalam pra-alfa tertutup. Tinggalkan emailmu dan kami akan menulis sekali, saat ada tempat untukmu.","interest.email":"Emailmu","interest.which":"Tes yang mana?","interest.alpha":"Alfa tertutup: awal, kasar, banyak perubahan","interest.beta":"Beta: lebih stabil, nanti","interest.both":"Salah satu, mana yang duluan","interest.submit":"Masukkan aku ke daftar","interest.thanks":"Terima kasih! Kamu sudah ada di daftar.","licence.title":"AI-gile: lisensi bisnis","licence.description":"Memakai AI-gile untuk bisnismu? Ajukan lisensi bisnis gratis.","licence.h1":"📜 Lisensi bisnis","licence.lede":"Memakai AI-gile di tempat kerja? Ceritakan siapa kamu dan apa yang kamu kerjakan. Kalau bermanfaat, lisensinya gratis.","licence.company":"Perusahaan","licence.website":"Situs web","licence.what":"Bidang usahamu","licence.how":"Bagaimana ini membantu dunia","licence.email":"Email","licence.submit":"Ajukan","licence.thanks":"Terima kasih! Kami akan membalas lewat email.","status.title":"Status AI-gile","status.h1":"Status AI-gile","status.quiet":"Semua tenang","status.intro":"Apakah AI-gile sedang berjalan? Halaman ini memeriksa situs web, berbagi papan, panggilan, dan unduhan setiap 5 menit.","status.up":"Berjalan (menjawab dalam {ms} ms)","status.slow":"Tidak menjawab pemeriksaan terakhir, mencoba lagi","status.down":"Mati: tidak menjawab dua pemeriksaan terakhir","status.svc.web":"Situs web","status.svc.web.offers":"Situs ini: apa itu AI-gile, dan formulir minat","status.svc.boards":"Berbagi papan","status.svc.boards.offers":"Papan publik, pesan antarteman, dan undangan","status.svc.calls":"Panggilan","status.svc.calls.offers":"Suara, video, dan berbagi layar di AI-gile","status.svc.download":"Unduhan","status.svc.download.offers":"Penginstal Windows dan tautan undangan","status.checking":"Memeriksa…","status.offline":"Layanan status belum terjangkau (mencoba lagi)","status.updated":"diperbarui {ago}","status.justNow":"baru saja","status.min":"{n} menit lalu","status.hours":"{n} jam lalu","status.days":"{n} hari lalu","privacy.title":"AI-gile: apa yang kami simpan","privacy.h1":"Apa yang kami simpan","privacy.lede":"Singkatnya: hanya yang kamu kirim ke kami, dan tidak lama.","privacy.only":"Hanya yang kamu kirim ke kami: yang kamu ketik di formulir, seperti emailmu. Tidak ada hal lain tentang dirimu.","privacy.sealed":"Datanya disegel sehingga server kami tidak bisa membacanya: di browsermu sebelum dikirim (di browser lama, begitu tiba). Hanya papan kami sendiri yang bisa membukanya.","privacy.server":"Data dihapus dari server begitu sampai di papan kami. Apa pun yang masih ada di sana setelah 30 hari tetap dihapus.","privacy.board":"Kami menyimpannya di papan kami hanya sampai kami membalasmu, lalu menghapusnya juga dari sana.","privacy.none":"Tanpa pelacak, tanpa cookie, tanpa analitik.","privacy.local":"Bahasa dan pilihan mode terang atau gelapmu tetap di browsermu sendiri. Tidak pernah dikirim ke kami.","privacy.ask":"Ingin dihapus lebih cepat? Balas email kami dan bilang saja.","live.h2":"Lihat proses pembuatannya, langsung","live.caption":"Setiap kartu disembunyikan: Anda melihat bentuk pekerjaannya, bukan kata-katanya.","live.watching.one":"langsung: {n} menonton","live.watching.other":"langsung: {n} menonton","live.last.now":"Kartu terakhir dipindahkan baru saja","live.last.min.one":"Kartu terakhir dipindahkan {n} menit lalu","live.last.min.other":"Kartu terakhir dipindahkan {n} menit lalu","live.last.hour.one":"Kartu terakhir dipindahkan {n} jam lalu","live.last.hour.other":"Kartu terakhir dipindahkan {n} jam lalu","live.last.day.one":"Kartu terakhir dipindahkan {n} hari lalu","live.last.day.other":"Kartu terakhir dipindahkan {n} hari lalu","live.offline":"Papan langsung sedang istirahat sebentar. Cek lagi nanti ya.","live.cols":"Backlog|Akan dikerjakan|Dikerjakan|Tim memeriksa|Giliranmu tes|Untuk tim|Selesai"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Didelegasikan."]},{"n":2,"texts":["Kanban robot.","Agen, tertata.","Ide, jadi."]},{"n":3,"texts":["Kanban untuk robot.","Ide jadi fitur.","Kanban agen gratis."]},{"n":5,"texts":["Papan kanban yang dijalankan agen.","Kamu menulis kartu. Agen membangun.","Gratis, lokal, teruji, agak konyol."]},{"n":8,"texts":["Papan kanban gratis tempat agen AI bekerja.","Tulis ide. Agen membangunnya. Kamu menyetujui.","Agile untuk satu manusia dan banyak robot sabar."]},{"n":13,"texts":["Papan kanban di komputermu, tempat agen AI mengambil kartu, mengerjakannya, lalu mengembalikannya padamu.","Tulis sebuah ide. Tim agen membangunnya, lalu seorang penguji memeriksanya sebelum sampai ke kamu.","Gratis, tanpa akun, tanpa pelacak: satu papan, beberapa robot, dan kamu yang memegang kendali."]},{"n":21,"texts":["AI-gile adalah papan kanban untuk bekerja bersama agen pemrograman AI. Mereka mengambil kartunya; kamu yang mengetes dan menyetujuinya.","Setiap proyek punya seorang lead dan tim agen AI. Beri komentar di kartu mana pun, dan tim langsung bekerja.","Papan tugas pribadi yang gratis dan berjalan di komputermu sendiri. Pekerjanya robot. Yang berkata ya adalah kamu."]},{"n":34,"texts":["Kamu menaruh ide di sebuah papan. Tim agen AI mengubahnya jadi fitur yang berfungsi, mengetesnya, lalu menyerahkannya kembali dengan langkah-langkah untuk dicoba. Tidak ada yang dianggap selesai sebelum kamu bilang begitu.","AI-gile adalah papan kanban buatan sendiri yang dibuat Rich dengan banyak bantuan dari agen-agen yang kini diurusnya. Gratis, berjalan di komputermu, dan dibagikan ke teman-teman, bukan dijual.","Bayangkan papan kanban biasa, dengan kolom dari Backlog sampai Selesai, hanya saja kartunya diambil oleh agen AI. Mereka melaporkan kemajuan, bertanya saat buntu, dan selalu menunggu acungan jempolmu."]},{"n":55,"texts":["AI-gile adalah papan kanban yang timnya terdiri dari agen AI. Setiap proyek punya lead yang merencanakan pekerjaan dan pembantu yang membangunnya. Saat sebuah fitur siap, penguji AI mencobanya dan mengambil tangkapan layar, lalu fitur itu mendarat di tumpukanmu. Setujui, atau beri komentar dan mereka mengerjakannya ulang.","Awalnya ini cara satu orang melacak banyak sesi pemrograman AI sekaligus, lalu tumbuh jadi papan sungguhan. Ia berjalan di mesinmu, tanpa akun, tanpa pelacak. Gratis untuk teman dan siapa pun yang penasaran. Ia juga belum selesai, jadi harap maklum kalau ada sisi kasar dan kejutan kecil.","Ini versi jujurnya. Kamu tetap harus punya ide, dan tetap harus memeriksa hasilnya. Yang dikerjakan AI-gile adalah semua yang ada di antaranya: menjaga kartu tetap urut, membangunkan agen yang tepat saat kamu berkomentar, menunjukkan persis apa yang berubah, dan menyimpan semuanya dalam satu tumpukan pendek untukmu."]},{"n":89,"texts":["AI-gile adalah papan kanban gratis yang kamu jalankan di komputermu sendiri. Alih-alih orang, setiap proyek punya tim agen AI: seorang lead yang mengubah ide-idemu jadi kartu dan rencana, dan pembantu yang mengambil kartu sesuai urutan prioritas. Setelah sesuatu selesai dibangun, penguji AI mengikuti langkah tesnya dan menunjukkan apa yang dilihatnya. Lalu hasilnya menunggu di satu tumpukan bernama Untukmu. Kamu menyetujuinya, atau memberi komentar dan tim mencoba sekali lagi. Tidak ada yang sampai ke Selesai tanpa kamu.","Beberapa fitur yang mungkin tak kamu duga. Penjaga malam mengisi kolom Akan dikerjakan selagi kamu tidur, dengan memilih kartu yang tidak butuh jawabanmu. Penghitung token menunjukkan berapa banyak yang dipakai agen hari ini dan minggu ini, dan Mode Tanpa Token menyuruh mereka berhenti menghabiskan. Kamu bisa berkirim pesan dengan teman, dan pesan pribadi dienkripsi ujung ke ujung. Papan ini berbahasa sekitar 120 bahasa, termasuk Belanda, Flemish, bajak laut, dan Klingon. Semuanya tanpa biaya sepeser pun, dan tak ada yang berusaha menjualnya padamu.","AI-gile adalah proyek kecil pribadi, bukan perusahaan. Rich ingin mengurus beberapa proyek pemrograman AI tanpa membuka tiap aplikasi untuk mengeceknya, jadi ia dan para agen membuat papan untuk itu, lalu memakai papan itu untuk membangun sisanya. Statusnya pra-alfa tertutup, artinya ia berfungsi, kurang lebih, untuk segelintir teman. Tidak ada halaman harga, tidak ada newsletter, dan tidak ada rencana pertumbuhan. Kalau kedengarannya berguna, kamu bisa minta mencobanya saat dibuka sedikit lebih lebar."]},{"n":144,"texts":["AI-gile adalah papan kanban untuk satu manusia dan banyak agen AI. Ia berjalan di komputermu sendiri dan sepenuhnya gratis. Kamu menambahkan proyek, dan setiap proyek mendapat lead beserta tim kecil. Kamu ngobrol dengan lead, agak mirip Discord, dan menjelaskan sebuah ide; lead mengubahnya jadi kartu dan rencana, lalu menunggu kamu menekan Go. Tim mengerjakan kartu sesuai urutan prioritas, memakai antarmuka baris perintah sederhana yang dibuat untuk model bahasa. Sebelum apa pun kembali kepadamu, penguji AI mengikuti langkah-langkahnya di salinan aplikasi dan melampirkan tangkapan layar. Pekerjaan yang selesai mendarat di tumpukanmu bersama berkas yang berubah dan diff-nya. Kamu menyetujuinya, atau meninggalkan komentar, lalu tim bangun dan mencoba lagi. Hanya kamu yang bisa memindahkan kartu ke Selesai.","Kira-kira begini sehari bersama AI-gile. Malam hari kamu meninggalkan beberapa komentar: tombol ini salah tempat, daftar itu harus diurutkan, bisakah ada mode gelap. Kamu pergi tidur. Para agen membaca komentarnya, membuat perubahan, mengetesnya, dan menyerahkannya kembali padamu. Kalau kolom Akan dikerjakan kosong, penjaga malam mengisinya dari backlog dengan kartu yang tidak butuh jawabanmu. Pagi harinya ada satu tumpukan pendek: beberapa pertanyaan dan beberapa hal untuk dicoba, masing-masing dengan langkah yang bisa diikuti orang mengantuk dan tangkapan layar yang membuktikannya berfungsi. Kamu menelusurinya, menyetujui yang bagus dan mengembalikan sisanya. Penghitung token menunjukkan pemakaiannya, dan Mode Tanpa Token siap untuk minggu-minggu hemat. Kalau ada yang kurang pas, tinggal komentar lagi dan siklusnya berulang. Lalu kamu sarapan, hal yang belum bisa dibantu para agen.","Pertama, apa yang bukan AI-gile. Ia bukan startup, tidak dijual, dan tak seorang pun mengumpulkan datamu. Ia papan gratis yang berjalan di komputermu, tanpa akun, tanpa pelacak, dan tanpa cookie. Yang ia adalah: satu tempat rapi untuk melihat semua proyek pemrograman AI sekaligus, dengan tim agen yang mengerjakan kartu dan kamu yang mengambil keputusan. Ia menggabungkan kartu yang berkaitan, membereskan judul yang berantakan, dan menjaga agar kodenya tetap ramping. Ia berbicara sekitar 120 bahasa, dari Belanda dan Flemish sampai bajak laut dan Klingon. Teman-teman bisa saling berkirim pesan, secara pribadi dan terenkripsi. Ia dibuat oleh Rich dan banyak agen yang sabar, kebanyakan dengan memakai dirinya sendiri. Statusnya pra-alfa tertutup, jadi di beberapa bagian masih kasar. Kalau kedengarannya seru, mintalah baik-baik dan kamu mungkin bisa masuk lebih awal."]}],"quips":{"1":"Satu kata. Berani. Mungkin terlalu berani.","3":"Tiga kata. Sudah lebih jujur daripada kebanyakan halaman produk.","8":"Delapan kata. Masih lebih pendek daripada satu stand-up.","21":"Panjangnya itu story point, omong-omong. Ya iyalah.","55":"Lima puluh lima kata. Dua kartu selesai selagi kamu membaca ini.","144":"Itu yang terpanjang. Tidak ada 233. Para agen sudah tidur."}},"timeline":{"first-idea.name":"Ide pertama","first-idea.line":"Percakapan pertama, sebelum ada satu baris kode pun.","first-board.name":"Papan pertama","first-board.line":"Papan yang melacak pembuatannya sendiri: kartu, kolom, seret dan lepas, proyek.","team-roles.name":"Tim dan peran","team-roles.line":"Profil agen, templat tim, ruang, dan siapa mengerjakan apa.","install.name":"Pemasangan dan rilis","install.line":"Satu zip yang bisa dipasang teman, pembaruan otomatis, kanal, dan kembali ke versi lama.","usage-saver.name":"Penghemat pemakaian","usage-saver.line":"Ukur biaya tiap proses, jaga kode tetap ramping, hemat batasmu.","friends.name":"Teman dan berbagi","friends.line":"Pesan pribadi, relai teracak, undangan, peran, dan proyek bersama.","languages.name":"Bahasa","languages.line":"Setiap teks layar dalam berkas bahasa, dimulai dari Belanda dan Flemish.","ai-tester.name":"Penguji AI","ai-tester.line":"Penguji memeriksa setiap serah terima lebih dulu dan menunjukkan apa yang dilihatnya.","website.name":"Situs web","website.line":"aigile.lol, teaser, dan lini masa ini.","streaming.name":"Obrolan dan streaming","streaming.line":"Discord, Twitch, OBS, mode streamer, GIF, dan emoji.","no-ai.name":"Edisi Tanpa AI","no-ai.line":"Papan untuk orang yang menulis kode tanpa AI, dan papan publik.","night-watch.name":"Penjaga malam","night-watch.line":"Seorang penjaga dan Scrum Master menjaga tim tetap fokus selagi kamu tidur.","p-more.name":"Yang lainnya","p-more.line":"Ide-ide kecil yang masih menunggu giliran.","p-android.name":"Ponsel dan Android","p-android.line":"Buka papanmu dari ponsel, lalu aplikasi Android asli.","p-release.name":"Alfa dan seterusnya","p-release.line":"Alfa tertutup, situs langsung, lalu beta.","p-languages.name":"Lebih banyak bahasa","p-languages.line":"130 bahasa, plus mode imersi untuk yang sedang belajar.","p-engines.name":"Lebih banyak mesin AI","p-engines.line":"Pilih Claude, Codex, Gemini, Copilot, atau Cursor untuk tiap agen.","p-pro.name":"Praktik profesional","p-pro.line":"Label risiko, gerbang merge, kartu insiden, dan pagar pengaman.","p-self.name":"Menjagamu","p-self.line":"Mode lelah, pengingat merawat diri, dan 4:20.","p-servers.name":"Server dan skala","p-servers.line":"Pengaturan server global, peran, dan perencanaan untuk berkembang.","p-livestream.name":"Tambahan streaming","p-livestream.line":"Obrolan Twitch, emoji kustom, dan tampilan langsung publik."},"words":{"button":"📖 Istilah industri","h":"📖 Istilah dijelaskan","intro":"Kata-kata yang kamu temui di AI-gile, dalam bahasa sederhana: membangunnya, mengubahnya dengan aman, menjaganya tetap berjalan untuk orang yang memakainya, dan bekerja sebagai tim bersama AI.","search":"Cari kata…","none":"Tidak ada kata yang cocok.","close":"Tutup","count":{"one":"{count} istilah","other":"{count} istilah"},"groups":[{"id":"build","name":"🛠️ Membangun"},{"id":"change","name":"🔀 Mengubah dengan aman"},{"id":"run","name":"🛎️ Menjalankan layanan"},{"id":"team","name":"🤝 Bekerja sebagai tim (dan dengan AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Folder kode proyek beserta seluruh riwayat commit-nya, biasanya juga disimpan di GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Jalur kerja terpisah di dalam kode, supaya perubahan bisa dibuat tanpa menyentuh versi utama.","also":["branch","cabang"]},{"id":"commit","g":"build","word":"Commit","text":"Cuplikan kode yang tersimpan, dengan catatan singkat tentang apa yang berubah. Kamu selalu bisa kembali ke salah satunya.","also":["commit"]},{"id":"push","g":"build","word":"Push","text":"Mengirim cuplikan tersimpan (commit) dari komputer ini ke GitHub, supaya punya cadangan dan bisa dibagikan."},{"id":"merge","g":"build","word":"Merge","text":"Menggabungkan perubahan sebuah branch kembali ke versi utama."},{"id":"pr","g":"build","word":"Pull request","text":"Meminta perubahan sebuah branch diperiksa dan digabungkan ke versi utama.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Merapikan kode tanpa mengubah fungsinya: file lebih kecil, nama lebih jelas, lebih sedikit pengulangan."},{"id":"bug","g":"build","word":"Bug","text":"Sesuatu yang tidak berfungsi sebagaimana mestinya.","also":["bug"]},{"id":"test","g":"build","word":"Tes","text":"Mencoba pekerjaan yang sudah jadi untuk memastikan hasilnya sesuai permintaan, sebelum kamu menerimanya.","also":["tes","test"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Singkatan dari quality assurance (jaminan kualitas): pemeriksaan otomatis yang berjalan sebelum apa pun live. Saat QA merah, ada yang gagal, dan belum bisa live sampai itu diperbaiki.","also":["pemeriksaan kualitas","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Merilis versi baru agar bisa dipakai, misalnya ke server tempat orang memakainya."},{"id":"release","g":"change","word":"Rilis","text":"Sekumpulan pekerjaan selesai yang diberi nama dan live bersama-sama, dengan catatan singkat tentang apa yang berubah. 🚀 Rilis menulis catatannya dari kartu yang sudah selesai.","also":["release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Kembali ke versi terakhir yang berjalan baik saat versi baru bermasalah. Di AI-gile ini membuat daftar periksa berisi langkah pembatalan yang ditulis di setiap perubahan.","also":["roll back","kembalikan versi"]},{"id":"live","g":"change","word":"Live","text":"Versi asli yang dipakai orang, bukan salinan untuk mencoba-coba. Developer juga menyebutnya production.","also":["production","produksi"],"noTip":1},{"id":"change","g":"change","word":"Perubahan","text":"Perubahan terencana pada sesuatu yang diandalkan orang, ditulis lebih dulu: apa, kenapa, risikonya, kapan, dan cara membatalkannya. Mulai dengan 🔀 Ajukan perubahan.","also":["permintaan perubahan","change request"],"noTip":1},{"id":"risk","g":"change","word":"Risiko","text":"Sesuatu yang bisa salah, diberi skor menurut seberapa mungkin terjadi dan seberapa parah akibatnya. ⚠️ Risiko menyimpannya dalam satu daftar, skor tertinggi di atas, masing-masing dengan tanggal untuk ditinjau lagi.","also":["daftar risiko","risk","risk register"]},{"id":"chgwin","g":"change","word":"Jendela perubahan","text":"Waktu ketika perubahan boleh live, misalnya Selasa malam yang sepi. Di luar jendela, kartu perubahan tidak bisa diselesaikan, kecuali darurat.","also":["change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Voting cepat tepat sebelum perubahan live: setiap orang yang harus menyetujui bilang Go atau No go. Baru lanjut kalau mereka sepakat.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Persetujuan","text":"Menunggu kata ya sebelum pekerjaan dimulai. Kartu yang diajukan teman, atau perubahan, menunggu di ✅ Persetujuan sampai kamu menyetujui atau menolaknya.","also":["approval"]},{"id":"quiettime","g":"change","word":"Waktu tenang","text":"Rentang waktu, seperti saat stream, demo atau malam hari, ketika tidak ada yang live. Tim tetap bekerja dan menguji, tapi live menunggu sampai selesai. Di tempat lain ini disebut change freeze.","also":["change freeze","pembekuan perubahan"]},{"id":"service","g":"run","word":"Layanan","text":"Sesuatu yang kamu bangun dan diandalkan orang, seperti situs web atau aplikasi, yang dirawat supaya tetap berjalan. Centang “Proyek ini adalah layanan” lalu tulis apa yang ditawarkan, siapa yang memakainya, dan siapa yang siaga.","also":["service","servis"]},{"id":"uptime","g":"run","word":"Cek uptime","text":"Pemeriksaan otomatis, tiap beberapa menit, bahwa layananmu masih merespons. Kalau gagal beberapa kali berturut-turut, AI-gile membuka kartu insiden sendiri.","also":["uptime","uptime check"]},{"id":"statuspage","g":"run","word":"Halaman status","text":"Halaman publik yang menunjukkan apakah layanan berjalan (hijau, oranye atau merah) beserta kabar terbarunya, jadi orang yang memakainya bisa mengecek sendiri tanpa harus bertanya.","also":["status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Tempat masuknya pertanyaan dan laporan dari orang-orang yang memakai layananmu. AI-gile memilah masing-masing menjadi permintaan, insiden, atau ide, dan memberi tahu kalau sepertinya sudah pernah dilaporkan.","also":["meja layanan","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Permintaan layanan","text":"Seseorang meminta hal yang biasa, seperti akun baru atau sedikit bantuan, bukan melaporkan ada yang rusak. Permintaan menunggu gilirannya; insiden didahulukan.","also":["permintaan-permintaan layanan"]},{"id":"incident","g":"run","word":"Insiden","text":"Sesuatu yang rusak saat ini bagi orang yang memakainya, misalnya situs web mati. Kartu 🔥 insiden menyalip antrean: membuatnya berjalan lagi adalah yang utama.","also":["incident"]},{"id":"major","g":"run","word":"Insiden besar","text":"Insiden yang parah: banyak orang terdampak, atau uang atau data dalam bahaya. Satu tombol mengerahkan semua tim (swarm), membangunkan siapa pun yang siaga, dan meminta kabar status tiap 30 menit.","also":["major incident"]},{"id":"oncall","g":"run","word":"Siaga","text":"Menjadi orang yang menanggapi saat ada yang rusak, bahkan di malam hari. Setiap layanan punya anggota tim yang siaga dan dibangunkan pertama untuk insidennya.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Batas waktu balasan","text":"Berapa lama kartu boleh menunggu balasan pertama, misalnya satu jam untuk insiden. Setelah itu muncul jam merah, supaya tidak ada yang diam-diam terlupakan. Disebut juga target respons.","also":["target respons","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Tinjauan singkat setelah insiden: apa yang terjadi, apa yang membantu, dan apa yang perlu diubah, tanpa menyalahkan siapa pun. Insiden tidak bisa ditutup tanpanya.","also":["postmortem","post-incident review","tinjauan pasca-insiden"]},{"id":"problem","g":"run","word":"Masalah","text":"Penyebab tersembunyi di balik satu insiden atau lebih. Kartu 🧩 masalah mengumpulkan insiden yang terus kembali, supaya penyebabnya ditemukan dan diperbaiki untuk selamanya.","also":["problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Akar masalah","text":"Alasan sebenarnya kenapa sesuatu rusak, bukan sekadar apa yang kamu lihat salah. Perbaiki akar masalahnya dan insiden berhenti kembali.","also":["root cause","akar penyebab"]},{"id":"workaround","g":"run","word":"Solusi sementara","text":"Cara menjaga semuanya tetap berjalan sampai perbaikan sebenarnya siap, misalnya me-restart sesuatu saat macet. Ditulis di kartu masalah supaya tidak ada yang perlu mencarinya lagi.","also":["workaround"]},{"id":"knownerror","g":"run","word":"Kesalahan yang diketahui","text":"Masalah yang penyebabnya sudah dipahami dan punya solusi sementara, tapi belum diperbaiki. 🧩 Kesalahan yang diketahui mendaftarnya, supaya semua orang memakai solusi sementara itu alih-alih menggali lagi.","also":["known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Petunjuk langkah demi langkah untuk memperbaiki jenis gangguan yang sudah dikenal, supaya dikerjakan dengan cara yang sama, cepat, setiap kali. Setelah insiden besar, tim bisa mengusulkan satu untuk kamu OK-kan.","also":["runbooks"]},{"id":"ci","g":"run","word":"Item konfigurasi","text":"Satu hal yang diandalkan layananmu, seperti server, domain, sertifikat, kunci, atau pemasok. 🗂️ Item konfigurasi mendaftarnya per layanan, supaya kamu bisa melihat apa yang terdampak insiden dan apa yang perlu diperbarui atau dicadangkan.","also":["item-item konfigurasi","configuration item"]},{"id":"expiry","g":"run","word":"Tanggal kedaluwarsa","text":"AI-gile memantau tanggal seperti kapan sertifikat atau domain habis masa berlakunya. Dalam 30 hari sebelum tanggal itu ia membuat satu kartu untuk memperpanjangnya, supaya tidak ada yang tiba-tiba berhenti bekerja.","also":["tanggal-tanggal kedaluwarsa","kedaluwarsa","pantauan kedaluwarsa"]},{"id":"backup","g":"run","word":"Cadangan","text":"Salinan datamu yang disimpan dari sebelumnya, untuk diandalkan kalau ada yang hilang atau rusak. AI-gile membuat cadangan papan-papanmu setiap hari.","also":["backup","backups"]},{"id":"restore","g":"run","word":"Pulihkan","text":"Mengembalikan data dari cadangan. Cadangan baru benar-benar berarti kalau kamu tahu itu bisa dipulihkan, jadi sesekali patut dicoba.","also":["memulihkan","dipulihkan","restore"]},{"id":"svcreview","g":"run","word":"Tinjauan layanan","text":"Melihat kembali satu bulan sebuah layanan: insiden yang dibuka dan diperbaiki, seberapa cepat orang mendapat jawaban, uptime, dan token yang terpakai. Tinjauan bulanan menampilkannya untuk tiap layanan.","also":["tinjauan-tinjauan layanan","tinjauan bulanan"]},{"id":"accessreview","g":"run","word":"Tinjauan akses","text":"Memeriksa tiap 90 hari siapa yang masih bisa masuk: tautan berbagi, peran teman, dan rahasia yang disimpan. Kamu mempertahankan atau menghapus masing-masing, supaya akses lama tidak tertinggal.","also":["tinjauan-tinjauan akses"]},{"id":"improvements","g":"run","word":"Daftar perbaikan","text":"Semua hal yang diputuskan tim untuk diperbaiki, di satu tempat: saran retro, tindakan tinjauan, dan perbaikan masalah, masing-masing dengan statusnya. Ada di bawah 📈 Perbaikan.","also":["daftar-daftar perbaikan","perbaikan"]},{"id":"tokencap","g":"run","word":"Batas token","text":"Batas bulanan untuk token yang boleh dipakai agen-agen sebuah layanan. Di 80% kamu mendapat peringatan; di 100% pekerjaan latar mereka menunggu sampai bulan depan atau sampai kamu menaikkan batasnya.","also":["batas-batas token","token cap"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ide dan pekerjaan yang belum direncanakan. Tidak ada yang dikerjakan di sana sampai dipindah ke Akan dikerjakan."},{"id":"sprint","g":"team","word":"Sprint","text":"Rentang kerja singkat (biasanya satu atau dua minggu) dengan sekumpulan kartu yang disepakati untuk diselesaikan.","also":["sprint"]},{"id":"standup","g":"team","word":"Stand-up","text":"Check-in singkat: apa yang dikerjakan tiap anggota tim, apa yang akan dikerjakan berikutnya, dan apa yang menghambat.","also":["standup","stand-up"]},{"id":"kanban","g":"team","word":"Kanban","text":"Board berkolom (Akan dikerjakan, Dikerjakan, Selesai) tempat kartu bergerak dari kiri ke kanan seiring pekerjaan berjalan."},{"id":"wip","g":"team","word":"Batas WIP","text":"Work in progress: jumlah kartu maksimal yang sebaiknya ada di satu kolom, supaya tim menyelesaikan sesuatu sebelum memulai yang lain.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"Daftar periksa singkat tim tentang arti “selesai”, misalnya sudah dites dan dijelaskan, sebelum kartu diserahkan kepadamu. Kembarannya, Definition of Ready, menyatakan kapan kartu cukup jelas untuk dimulai.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Tumpukan tes","text":"Kartu selesai yang menunggu kamu coba, satu per satu. Terima satu atau kembalikan dengan catatan, lalu kartu berikutnya muncul.","also":["test pile"]},{"id":"retro","g":"team","word":"Retro","text":"Melihat kembali cara tim bekerja, untuk menyepakati satu hal yang bisa dibuat lebih baik. Di AI-gile, retro mengusulkan perubahan pada cara kerja tim, lalu kamu bilang Gas atau Belum.","also":["retrospektif","retrospective"]},{"id":"peerreview","g":"team","word":"Peer review","text":"Sepasang mata kedua: AI lain memeriksa hasil kerja setiap kartu sebelum sampai ke kamu, jadi lebih sedikit kesalahan yang lolos.","also":["code review","tinjauan sejawat"]},{"id":"swarm","g":"team","word":"Swarm","text":"Semua turun tangan: setiap tim meninggalkan pekerjaan lain untuk membantu satu proyek mendesak sampai beres. Proyek lain menunggu sementara itu.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Orang yang menjaga pekerjaan tetap mengalir: melihat kartu yang macet, mendorong tim, dan mengingatkanmu apa yang sedang menunggu. Di AI-gile, Lead Scrum Master melakukan ini di semua proyek.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agen","text":"AI yang bekerja sendiri pada suatu tugas: membaca kode, membuat perubahan, menjalankan pengecekan, lalu melapor balik.","also":["agen","agent"]},{"id":"token","g":"team","word":"Token","text":"Satuan penghitungan pemakaian AI: kira-kira beberapa huruf teks yang dibaca atau ditulis. Makin sedikit token, makin banyak sisa paketmu.","also":["token","tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Perintah kecil yang berjalan sendiri pada saat tertentu, mis. ketika sesi AI dimulai, supaya tim mendengar komentarmu.","also":["hook","hooks"]}]}};
